package org.opensourcepingpong.rating.domain;
public final class RatingCalculator {private RatingCalculator(){} public static RatingChange calculate(int a,int b,Winner winner){if(a<400||b<400)throw new IllegalArgumentException();int diff=Math.abs(a-b);int highWin,lowWin;if(diff<=12){highWin=lowWin=8;}else if(diff<=37){highWin=7;lowWin=10;}else if(diff<=62){highWin=6;lowWin=13;}else if(diff<=87){highWin=5;lowWin=16;}else if(diff<=112){highWin=4;lowWin=20;}else if(diff<=137){highWin=3;lowWin=25;}else if(diff<=162){highWin=2;lowWin=30;}else if(diff<=187){highWin=2;lowWin=35;}else if(diff<=212){highWin=1;lowWin=40;}else if(diff<=237){highWin=1;lowWin=45;}else{highWin=0;lowWin=50;}boolean aHigh=a>=b;boolean aWon=winner==Winner.A;int theoretical=(aHigh==aWon)?highWin:lowWin;int loser=aWon?b:a;int actual=Math.min(theoretical,loser-400);int da=aWon?actual:-actual;return new RatingChange(da,-da,a+da,b-da);} }
